            if isinstance(cur,list) and part.isdigit(): cur=int(part)
            else: raise QueryError(f'unexpected type: expected map, got {type(cur).__name__}')
    return cur

def main():
    args=sys.argv[1:]
    if args and args[0]=='version': print('3.11.0'); return 0
    if args and args[0]=='query': args=args[1:]
    parser=argparse.ArgumentParser(prog='dasel',add_help=True)
    parser.add_argument('query',nargs='?'); parser.add_argument('-i','--in',dest='infmt',default='json'); parser.add_argument('-o','--out',dest='outfmt'); parser.add_argument('--root',action='store_true'); parser.add_argument('--compact',action='store_true'); parser.add_argument('--read-flag',action='append',default=[]); parser.add_argument('--write-flag',action='append',default=[]); parser.add_argument('--rw-flag',action='append',default=[]); parser.add_argument('--var',action='append',default=[])
    try: ns=parser.parse_args(args)
    except SystemExit as e: return e.code
    raw=sys.stdin.read()
    try:
        inf=ns.infmt.lower(); delimiter=','
        for f in ns.read_flag+ns.rw_flag:
            if f.startswith('csv-delimiter='): delimiter=f.split('=',1)[1]
        if inf=='json': data=json.loads(raw)
        elif inf=='csv': data=parse_csv(raw,delimiter)
        elif inf=='toml':
            import tomllib; data=tomllib.loads(raw)
        elif inf in ('yaml','yml'):
            # Basic YAML scalar/object support
            data=parse_simple_yaml(raw)
        else: raise QueryError('unsupported input format')
        result=evalq(data,ns.query or '')
        if ns.root: result=data
        outf=(ns.outfmt or inf).lower()
        if outf=='csv': out=write_csv(result,delimiter)
        else:
